        var doc = JsonSerializer.Deserialize<GoldenFile>(File.ReadAllText(path), s_options)!;
        return doc.Scenarios;
    }

    private record GoldenFile(int SchemaVersion, List<GoldenItem> Scenarios);
}

internal static class RubricLoader
